/* @autogenerated */
package net.civeira.phylax.feature.observe.ingest;

import java.util.Collection;

import io.opentelemetry.sdk.common.CompletableResultCode;
import io.opentelemetry.sdk.trace.data.SpanData;
import io.opentelemetry.sdk.trace.export.SpanExporter;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.source.SourceRegistry;

/**
 * Receives the spans of this process (OpenTelemetry) and those that the OTLP collector receives
 * from the other origins, and queues them for the store. It has no build condition, so it keeps
 * working when telemetry.yaml also forwards the spans to an external collector.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ObserveSpanExporter implements SpanExporter {

  private final TelemetryMapper mapper;
  private final IngestContext context;
  private final ObservePipeline pipeline;
  private final SourceRegistry registry;

  @Override
  public CompletableResultCode export(final Collection<SpanData> spans) {
    boolean fromRequest = context.inRequest();
    var keySource = context.keySource();
    for (SpanData span : spans) {
      var source = mapper.resolve(fromRequest, keySource, span.getResource().getAttributes());
      if (source.isEmpty()) {
        registry.drop(String.valueOf(span.getResource().getAttributes()
            .get(io.opentelemetry.api.common.AttributeKey.stringKey("service.name"))));
        continue;
      }
      registry.seen(source.get().code());
      mapper.span(source.get(), span).ifPresent(pipeline::offer);
    }
    return CompletableResultCode.ofSuccess();
  }

  @Override
  public CompletableResultCode flush() {
    return CompletableResultCode.ofSuccess();
  }

  @Override
  public CompletableResultCode shutdown() {
    return CompletableResultCode.ofSuccess();
  }
}
